export const WAKE_FEATURE_COUNT=WAKE_FEATURES.length;
export function wakeSnapshot(state={}){const p=state.wakeProgress||{};return {range:"4001–4500",total:WAKE_FEATURE_COUNT,verified:Object.values(p).filter(x=>x?.status==="verified").length,building:Object.values(p).filter(x=>x?.status==="building").length,planned:WAKE_FEATURE_COUNT-Object.values(p).filter(x=>x?.status==="verified"||x?.status==="building").length,preserveExisting:true,rule:"Wake features are additive and never remove existing Nori capabilities."};}
export function setWakeFeatureState(state,id,status="building",evidence=""){state.wakeProgress=state.wakeProgress||{};state.wakeProgress[id]={status,evidence,updatedAt:Date.now(),preserveExisting:true};return state;}
export function wakePolicy(){return {wakeWord:true,twoClap:true,patientListening:true,quietIsNotFailure:true,breathIsNotCommand:true,ttsEnabled:true,gracefulDegradation:true,userControlledPrivacy:true,backgroundWake:"requires native Android implementation and permission",preserveExisting:true};}
export function wakeIntent(text=""){const t=text.toLowerCase();return {wakeWord:/\\bnori\\b|\\bhey nori\\b/.test(t),question:/\\bwhat can i ask|what can you do\\b/.test(t),status:/\\bstatus|how am i doing\\b/.test(t),presentation:/\\bpresentation\\b/.test(t),study:/\\bstudy|homework|lesson\\b/.test(t),help:/\\bhelp\\b/.test(t)};}
